ization","sources":[{"reference":"https://github.com/MuncleUscles/p-vs-np/pull/7","title":"Credited assignment locality for CNF evaluation","authors":["Open Mathematics project contributors"],"relationship":"Imports exact definitions and uses the credited theorem only where the residual variable invariant makes assignment extension evaluation-preserving. Upstream attribution is a separate decision within this result's fixed budget.","priority_evidence":"Credited record pr-7-672f1fa46a61-0d05d194a602 pins raw bundle SHA-256 2199be74880768cf37366356ae1701e8f3582928f2bd55dce8ea5041d5596e00. Its original contribution remains separate; no independent discovery is asserted here."},{"reference":"https://github.com/MuncleUscles/p-vs-np/blob/758d9b3b559dc882a3680c60bd3969c4f9f444df/goals/cnf_restriction/TASK.md","title":"Previously published one-variable CNF restriction specification","authors":["Open Mathematics project contributors"],"relationship":"Prior specification motivating a concrete SAT simplification component. The arbitrary-partial-assignment implementation and bundled proof here were constructed for this submission; no proof of the proposed target was copied from that task page.","priority_evidence":"The immutable prior repository commit predates this submission. Restriction and unit-propagation semantics were already identified there as established mathematics, with Logic and Mechanized Reasoning listed as background."},{"reference":"https://github.com/leanprover/lean4/blob/v4.19.0/src/Init/Data/List/Lemmas.lean","title":"Lean 4.19 Core List lemmas","authors":["Lean contributors"],"relationship":"Constructive list filter/map membership and Boolean fold facts support the new proof. Core library facts and established SAT semantics are explicitly prior work.","priority_evidence":"Pinned Lean v4.19.0 predates the pilot. No global novelty, priority, first-formalization or exhaustive literature-search claim is made."}],"discovery_basis":"This is disclosed project-agent work on known mathematical infrastructure. The credited locality bundle, local prior restriction specification, pinned Core lemmas, and the actual rejected finite-support verdict were inspected. The new proof and transformation were constructed as a cohesive independent component, not a renamed retry. No exhaustive external literature search was performed."},"dependencies":["pr-7-672f1fa46a61-0d05d194a602"],"verified_dependencies":[{"id":"pr-7-672f1fa46a61-0d05d194a602","artifact_hash":"2199be74880768cf37366356ae1701e8f3582928f2bd55dce8ea5041d5596e00","proof_body_use":true}],"formal_statement":"∀ (p : Nat → Option Bool) (f : CNF), (∀ n : Nat, n ∈ CNFVars (RestrictedCNF p f) → n ∈ CNFVars f ∧ p n = none) ∧ List.length (RestrictedCNF p f) ≤ List.length f ∧ (∀ a : Nat → Bool, CNFValue a (RestrictedCNF p f) = CNFValue (ExtendedAssignment p a) f ∧ ExtendsPartial p (ExtendedAssignment p a)) ∧ ((∃ a : Nat → Bool, CNFValue a (RestrictedCNF p f) = true) ↔ ∃ a : Nat → Bool, ExtendsPartial p a ∧ CNFValue a f = true) ∧ (List.Mem [] (RestrictedCNF p f) → ¬ ∃ a : Nat → Bool, ExtendsPartial p a ∧ CNFValue a f = true) ∧ RestrictedCNF p (RestrictedCNF p f) = RestrictedCNF p f","proof":"{
  "version": 1,
  "definitions": [
    {
      "name": "CNF",
      "type": "Type",
      "value": "B_2199be74880768cf37366356ae1701e8f3582928f2bd55dce8ea5041d5596e00.CNF"
    },
    {
      "name": "CNFValue",
      "type": "(Nat → Bool) → CNF → Bool",
      "value": "B_2199be74880768cf37366356ae1701e8f3582928f2bd55dce8ea5041d5596e00.evalCNF"
    },
    {
      "name": "ClauseValue",
      "type": "(Nat → Bool) → List (Nat × Bool) → Bool",
      "value": "B_2199be74880768cf37366356ae1701e8f3582928f2bd55dce8ea5041d5596e00.evalClause"
    },
    {
      "name": "CNFVars",
      "type": "CNF → List Nat",
      "value": "B_2199be74880768cf37366356ae1701e8f3582928f2bd55dce8ea5041d5596e00.cnfVars"
    },
    {
      "name": "ReducedClause",
      "type": "(Nat → Option Bool) → List (Nat × Bool) → List (Nat × Bool)",
      "value": "fun p c => List.filter (fun l => Option.isNone (p l.1)) c"
    },
    {
      "name": "RestrictedCNF",
      "type": "(Nat → Option Bool) → CNF → CNF",
      "value": "fun p f => List.map (ReducedClause p) (List.filter (fun c => !(List.any c (fun l => p l.1 == some l.2))) f)"
    },
    {
      "name": "ExtendedAssignment",
      "type": "(Nat → Option Bool) → (Nat → Bool) → Nat → Bool",
      "value": "fun p a n => Option.getD (p n) (a n)"
    },
    {
      "name": "ExtendsPartial",
      "type": "(Nat → Option Bool) → (Nat → Bool) → Prop",
      "value": "fun p a => ∀ (n : Nat) (v : Bool), p n = some v → a n = v"
    }
  ],
  "statement": "∀ (p : Nat → Option Bool) (f : CNF), (∀ n : Nat, n ∈ CNFVars (RestrictedCNF p f) → n ∈ CNFVars f ∧ p n = none) ∧ List.length (RestrictedCNF p f) ≤ List.length f ∧ (∀ a : Nat → Bool, CNFValue a (RestrictedCNF p f) = CNFValue (ExtendedAssignment p a) f ∧ ExtendsPartial p (ExtendedAssignment p a)) ∧ ((∃ a : Nat → Bool, CNFValue a (RestrictedCNF p f) = true) ↔ ∃ a : Nat → Bool, ExtendsPartial p a ∧ CNFValue a f = true) ∧ (List.Mem [] (RestrictedCNF p f) → ¬ ∃ a : Nat → Bool, ExtendsPartial p a ∧ CNFValue a f = true) ∧ RestrictedCNF p (RestrictedCNF p f) = RestrictedCNF p f",
  "proof": "by\n  have clauseCore (p : Nat → Option Bool) (a : Nat → Bool) (c : List (Nat × Bool))\n      (ha : ExtendsPartial p a) (hn : List.any c (fun l => p l.1 == some l.2) = false) :\n      ClauseValue a (ReducedClause p c) = ClauseValue a c := by\n    apply Bool.eq_iff_iff.mpr\n    constructor\n    · intro hc\n      obtain ⟨l, hl, hval⟩ := List.any_eq_true.mp hc\n      obtain ⟨hlc, hfree⟩ := List.mem_filter.mp hl\n      exact List.any_eq_true.mpr ⟨l, hlc, hval⟩\n    · intro hc\n      obtain ⟨l, hl, hval⟩ := List.any_eq_true.mp hc\n      apply List.any_eq_true.mpr\n      refine ⟨l, ?_, hval⟩\n      apply List.mem_filter.mpr\n      refine ⟨hl, ?_⟩\n      cases hp : p l.1 with\n      | none => simp [hp]\n      | some b =>\n        have same : a l.1 = b := ha l.1 b hp\n        have hfixed : (p l.1 == some l.2) = true := by\n          simpa [B_2199be74880768cf37366356ae1701e8f3582928f2bd55dce8ea5041d5596e00.evalLiteral, hp, same] using hval\n        have hs : List.any c (fun l => p l.1 == some l.2) = true :=\n          List.any_eq_true.mpr ⟨l, hl, hfixed⟩\n        simp [hn] at hs\n  have compatibleCore (p : Nat → Option Bool) (f : CNF) (a : Nat → Bool)\n      (ha : ExtendsPartial p a) : CNFValue a (RestrictedCNF p f) = CNFValue a f := by\n    apply Bool.eq_iff_iff.mpr\n    constructor\n    · intro hf\n      apply List.all_eq_true.mpr\n      intro c hc\n      cases hh : List.any c (fun l => p l.1 == some l.2) with\n      | false =>\n        have kept : c ∈ List.filter (fun c => !(List.any c (fun l => p l.1 == some l.2))) f :=\n          List.mem_filter.mpr ⟨hc, by simp [hh]⟩\n        have member : List.Mem (ReducedClause p c) (RestrictedCNF p f) := List.mem_map.mpr ⟨c, kept, rfl⟩\n        have reduced := List.all_eq_true.mp hf (ReducedClause p c) member\n        change ClauseValue a c = true\n        rw [← clauseCore p a c ha hh]\n        exact reduced\n      | true =>\n        obtain ⟨l, hl, hfixed⟩ := List.any_eq_true.mp hh\n        have hp : p l.1 = some l.2 := by simpa using hfixed\n        have same := ha l.1 l.2 hp\n        apply List.any_eq_true.mpr\n        refine ⟨l, hl, ?_⟩\n        simp [B_2199be74880768cf37366356ae1701e8f3582928f2bd55dce8ea5041d5596e00.evalLiteral, same]\n    · intro hf\n      apply List.all_eq_true.mpr\n      intro c hc\n      obtain ⟨original, kept, equation⟩ := List.mem_map.mp hc\n      subst c\n      obtain ⟨member, notHit⟩ := List.mem_filter.mp kept\n      have hh : List.any original (fun l => p l.1 == some l.2) = false := by simpa using notHit\n      change ClauseValue a (ReducedClause p original) = true\n      rw [clauseCore p a original ha hh]\n      exact List.all_eq_true.mp hf original member\n  have extensionLaw (p : Nat → Option Bool) (a : Nat → Bool) :\n      ExtendsPartial p (ExtendedAssignment p a) := by\n    intro n v hn\n    simp [ExtendedAssignment, hn]\n  intro p f\n  have support : ∀ n : Nat, n ∈ CNFVars (RestrictedCNF p f) → n ∈ CNFVars f ∧ p n = none := by\n    intro n hn\n    obtain ⟨c, hc, hv⟩ := List.mem_flatMap.mp hn\n    obtain ⟨original, kept, equation⟩ := List.mem_map.mp hc\n    subst c\n    obtain ⟨member, notHit⟩ := List.mem_filter.mp kept\n    obtain ⟨l, hl, eqn⟩ := List.mem_map.mp hv\n    subst n\n    obtain ⟨hlc, hfree⟩ := List.mem_filter.mp hl\n    refine ⟨List.mem_flatMap.mpr ⟨original, member, List.mem_map.mpr ⟨l, hlc, rfl⟩⟩, ?_⟩\n    exact Option.isNone_iff_eq_none.mp hfree\n  have value (a : Nat → Bool) : CNFValue a (RestrictedCNF p f) = CNFValue (ExtendedAssignment p a) f := by\n    have same : ∀ n : Nat, n ∈ CNFVars (RestrictedCNF p f) → a n = ExtendedAssignment p a n := by\n      intro n hn\n      have info := support n hn\n      simp [ExtendedAssignment, info.2]\n    have localEqual := B_2199be74880768cf37366356ae1701e8f3582928f2bd55dce8ea5041d5596e00.result (RestrictedCNF p f) a (ExtendedAssignment p a) same\n    exact Eq.trans localEqual (compatibleCore p f (ExtendedAssignment p a) (extensionLaw p a))\n  refine ⟨support, ?_, ?_, ?_, ?_, ?_⟩\n  · simpa [RestrictedCNF] using List.length_filter_le (fun c => !(List.any c (fun l => p l.1 == some l.2))) f\n  · intro a\n    exact ⟨value a, extensionLaw p a⟩\n  · constructor\n    · intro h\n      obtain ⟨a, ha⟩ := h\n      refine ⟨ExtendedAssignment p a, extensionLaw p a, ?_⟩\n      rw [← value a]\n      exact ha\n    · intro h\n      obtain ⟨a, hp, ha⟩ := h\n      refine ⟨a, ?_⟩\n      rw [compatibleCore p f a hp]\n      exact ha\n  · intro empty models\n    obtain ⟨a, hp, ha⟩ := models\n    have remaining : CNFValue a (RestrictedCNF p f) = true := by\n      rw [compatibleCore p f a hp]\n      exact ha\n    have impossible := List.all_eq_true.mp remaining [] empty\n    simp [B_2199be74880768cf37366356ae1701e8f3582928f2bd55dce8ea5041d5596e00.evalClause] at impossible\n  · have unchanged (c : List (Nat × Bool)) (hc : List.Mem c (RestrictedCNF p f)) : ReducedClause p c = c := by\n      apply List.filter_eq_self.mpr\n      intro l hl\n      have member : l.1 ∈ CNFVars (RestrictedCNF p f) :=\n        List.mem_flatMap.mpr ⟨c, hc, List.mem_map.mpr ⟨l, hl, rfl⟩⟩\n      have info := support l.1 member\n      simp [info.2]\n    have keepAll : List.filter (fun c => !(List.any c (fun l => p l.1 == some l.2))) (RestrictedCNF p f) = RestrictedCNF p f := by\n      apply List.filter_eq_self.mpr\n      intro c hc\n      have noHit : List.any c (fun l => p l.1 == some l.2) = false := by\n        apply List.any_eq_false.mpr\n        intro l hl\n        have member : l.1 ∈ CNFVars (RestrictedCNF p f) :=\n          List.mem_flatMap.mpr ⟨c, hc, List.mem_map.mpr ⟨l, hl, rfl⟩⟩\n        have info := support l.1 member\n        simp [info.2]\n      simp [noHit]\n    change List.map (ReducedClause p) (List.filter (fun c => !(List.any c (fun l => p l.1 == some l.2))) (RestrictedCNF p f)) = RestrictedCNF p f\n    rw [keepAll]\n    have mapped : List.map (ReducedClause p) (RestrictedCNF p f) = List.map (fun c => c) (RestrictedCNF p f) :=\n      List.map_congr_left unchanged\n    simpa using mapped\n",
